import{_ as l,l as o,o as e,c as n,v as t,p,x as r,d,i as m,S as s}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"深度加权中间价","description":"","frontmatter":{"title":"深度加权中间价","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/depth-mid.md","filePath":"quant/depth-mid.md","lastUpdated":1789023840000}'),E={name:"quant/depth-mid.md"};function h(B,a,_,Q,u,A){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="深度加权中间价" tabindex="-1">深度加权中间价 <a class="header-anchor" href="#深度加权中间价" aria-label="Permalink to &quot;深度加权中间价&quot;">​</a></h1><div class="epigraph"><p>最优档只决定立刻成交一笔小单的价格；把若干档量加权之后，读数才开始接近「再往里走」时市场愿意给出的平均价。</p><footer>—— 据 Harris 对深度、冲击与可成交量的论述，以及 Cont 等人对限价簿事件的经验研究整理</footer></div><p><a href="/quant/microprice">微观价格</a> 用最优档量修正中点，回答的是下一小步往哪边偏。<a href="/quant/lob-structure">限价订单簿</a> 的更深层问题是：若要买 \\(Q\\) 股，沿卖档消耗会得到什么样的成交均价。深度加权中间价（depth-weighted mid）把多档价量收成一个公允读数，或显式按目标量走一遍簿，得到冲击调整后的价格。它与微价格同族——都是可见簿的函数——但信息集从 BBO 扩到前 \\(K\\) 档，因此对大单、对 ETF 成分冲击、对指数套利更有用，对下一毫秒的 tick 方向往往更钝。Harris 把深度当作价格压力的原材料；Cont 等人指出大的价格变动不再服从单一线性 OFI，而要沿深度积分。本篇写加权方式、目标量、以及它和 Kyle 冲击系数的接口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>中点与微价格对「无穷小」的下一笔有意义。执行与风控常问另一句：当前可见流动性下，完成规模 \\(Q\\) 的期望成交价是什么。只看 \\(a_1\\) 会过度乐观，因为 \\(Q\\) 可能打穿若干档；只看最深一档又会过度悲观，把远离市场的挂单当成可成交。需要把各档剩余量按与 BBO 的距离加权，或按真实撮合顺序做量加权均价（VWAP along the book）。</p><p>隐藏量与多市场使可见深度不是可成交深度。深度加权中间价永远是<strong>可见</strong>对象：它高估或低估真实冲击，取决于冰山与暗池。问题不是消灭这一误差，而是声明加权所用的层级，并在研究里把「可见冲击」与「事后实现冲击」分开。</p><h3 id="多档加权与冲击路径" tabindex="-1">多档加权与冲击路径 <a class="header-anchor" href="#多档加权与冲击路径" aria-label="Permalink to &quot;多档加权与冲击路径&quot;">​</a></h3><p>一种构造不指定 \\(Q\\)，只把前 \\(K\\) 档做对称加权：</p> \\[m_K=\\frac{\\sum_{k=1}^{K}w_k(b_k q^b_k+a_k q^a_k)}{\\sum_{k=1}^{K}w_k(q^b_k+q^a_k)}, \\]<p>\\(w_k\\) 可以是常数，或随档位指数衰减 \\(e^{-\\kappa(k-1)}\\)。\\(K=1\\) 且 \\(w_1=1\\) 时，若再按微价格那样对买卖交叉加权，就回到最优档读数；一般的 \\(m_K\\) 更接近「两侧深度的重心」。另一种构造指定方向与数量：买 \\(Q\\) 的可成交价 \\(P^{\\mathrm{buy}}(Q)\\) 是沿卖档累计消耗直到 \\(Q\\) 的量加权均价，卖同理，然后</p> \\[m(Q)=\\frac{P^{\\mathrm{buy}}(Q)+P^{\\mathrm{sell}}(Q)}{2} \\]<p>或直接把 \\(P^{\\mathrm{buy}}(Q)\\) 当标记。后者对执行更诚实：买卖冲击不必对称。簿在一侧极薄时，\\(P^{\\mathrm{buy}}(Q)\\) 可能不存在（深度不足），这本身就是流动性状态，应记为缺失而不是用中点填。</p><p><span class="marginnote">衰减权重 \\(\\kappa\\) 把远档当成不太可成交的意向，这与经验一致：远档取消率高、信息量低。\\(\\kappa\\) 不是结构参数，应与你关心的 \\(Q\\) 匹配：关心的量越大，\\(\\kappa\\) 应越小、或改用显式 \\(P(Q)\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>L2 上前 \\(K\\) 档价量即可算 \\(m_K\\) 与 \\(P(Q)\\)。\\(K\\) 的选择应报告累积深度分位数：例如覆盖过去中位主动单的两倍。权重与 \\(K\\) 在样本外锁定。预测下一跳方向时，\\(m_K\\) 通常弱于微价格；预测「接下来较大的中点移动」或解释大单冲击时，\\(m_K\\) 与 \\(P(Q)-m\\) 更相关。回归冲击</p> \\[\\Delta m=\\lambda Q+\\varepsilon \\]<p>若 \\(Q\\) 已大到打穿多档，线性会坏；改用 \\(P(Q)-m\\) 作为自变量，等于把簿几何当成已知的瞬时冲击函数，残差才是意外信息或隐藏流动性。</p><p>与 OFI 分工：OFI 是流量，深度加权价是状态。可以用深度加权价的变化作为因变量，看 OFI 是否仍线性——Cont 的结果在小变动上成立，大变动应改因变量。与 <a href="/quant/kyle-lambda">Kyle lambda</a> 对照：\\(\\lambda\\) 是把深度压成一个斜率；\\(P(Q)\\) 是把深度留成一条曲线。短窗、单标的，曲线更对；截面、日频，斜率更方便。</p><h3 id="衰减权重与目标成交量" tabindex="-1">衰减权重与目标成交量 <a class="header-anchor" href="#衰减权重与目标成交量" aria-label="Permalink to &quot;衰减权重与目标成交量&quot;">​</a></h3><p>指数衰减是在「不知道 \\(Q\\)」时的折中：近档权重大，避免一张远离市场的幽灵单把 \\(m_K\\) 拉走。目标量方法更干净，但 \\(Q\\) 必须来自策略：做市商的典型存货、ETF 篮子里该股的份额、或回测里的订单规模。用「当日成交量的 1%」当 \\(Q\\) 会让 \\(P(Q)\\) 在清淡时段打穿整张可见簿，读数变成最差档价格，因子全是流动性空洞而不是方向。</p><p>多市场应先合成全国最优深度再加权，否则本地 \\(m_K\\) 忽略他处可成交量。合成需要可比较的时间戳与费用调整，否则「更优」的远市场并不可执行。这与信息份额问题相关：价格发现可以发生在另一市场，而本地深度加权价仍只反映本地可执行性。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>瞬时冲击的机制是沿队列消耗：价格走多少取决于各档剩余量，不取决于事后才知道的「信息含量」。\\(P(Q)-m\\) 是这条路径的摘要。若随后深度重建、价格部分回抽，差额里有暂时成分；若中点留在新水平，差额里有信息或持久需求。这与价差分解的暂时/永久相同，只是冲击规模从「一笔」换成「给定 \\(Q\\)」。Kyle 的线性 \\(p=\\mu+\\lambda y\\) 相当于假设深度曲线是一条斜线；真实 LOB 是阶梯，小 \\(Q\\) 落在第一档（接近半价差加一点），大 \\(Q\\) 沿阶梯走，边际冲击上升。深度加权中间价保留阶梯，lambda 则把阶梯拟合成斜率。</p><p>冰山使可见 \\(P(Q)\\) 高估冲击：隐藏余量会在同一价位再切出来，实际均价优于可见路径。暗池使部分 \\(Q\\) 根本不走明簿。研究可用事后成交均价减可见 \\(P(Q)\\) 来估计隐藏流动性的贡献；负值表示可见簿悲观。同样，这是市场质量度量，不是把订单拆进隐藏字段以改变他人所见深度的操作说明。</p><h3 id="与微观价格、ofi-的分工" tabindex="-1">与微观价格、OFI 的分工 <a class="header-anchor" href="#与微观价格、ofi-的分工" aria-label="Permalink to &quot;与微观价格、OFI 的分工&quot;">​</a></h3><p>三套读数对应三种 \\(Q\\)。微价格：\\(Q\\) 约一档之内的下一笔。深度加权：\\(Q\\) 为若干档或指定规模。OFI：不问 \\(Q\\)，问刚刚发生的净事件如何移动中点。短窗 alpha 常用前两者的差 \\(m^\\ast-m\\) 或 \\(m_K-m\\)；冲击成本常用 \\(P(Q)\\)；毒性与做市报价常用 OFI。把三者同时放进一个「因子厨房」而不做共线诊断，系数无法解释。</p><p><span class="marginnote">用深度加权价当标记会让存货盈亏对远档挂单敏感。一张远离市场的大单进出，不改变可立即成交价，却能拉动 \\(m_K\\)。风控标记应限制 \\(K\\) 或使用 \\(P(Q)\\) 并给 \\(Q\\) 上限。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>可见档位数随交易所产品而变，十档与四十档的 \\(m_K\\) 不可比。涨跌停、集合竞价、盘后没有同一套连续深度。tick 很大时前 \\(K\\) 档可能在经济上已经离市场很远。没有 L2 就没有本对象；用成交 VWAP 去冒充 \\(P(Q)\\) 会混入你自己的成交与时间上的延迟。</p><p>不要把 \\(m_K\\) 序列送进 Hasbrouck 信息份额：它不是另一个市场的成交价，与中点共享同一张簿、同一噪声源，共同趋势分解没有识别。不要用 \\(P(Q)\\) 的日内变化当低频非流动性因子——那是 <a href="/quant/amihud-illiquidity">Amihud</a> 与日度 \\(\\lambda\\) 的工作；\\(P(Q)\\) 的水平随盘口秒级变化，加总方式必须另写。</p><p><span class="marginnote">A 股行情档位、对敲与涨跌停使可见深度的尾部难以解释。加权若包含远离涨跌停板的「深度」，会把无法成交的意向写进公允价。应先按可成交性截断档位。</span></p>',31)),(e(),p(s,null,{default:r(()=>[m(i,{id:"mermaid-85",class:"mermaid",graph:"flowchart%20TD%0A%20%20L1%5B%22%E6%9C%80%E4%BC%98%E6%A1%A3%22%5D%20--%3E%20MP%5B%22%E5%BE%AE%E4%BB%B7%E6%A0%BC%20%2F%20%E4%B8%AD%E7%82%B9%22%5D%0A%20%20LK%5B%22%E5%89%8D%20K%20%E6%A1%A3%E4%BB%B7%E9%87%8F%22%5D%20--%3E%20MK%5B%22%E8%A1%B0%E5%87%8F%E5%8A%A0%E6%9D%83%20m_K%22%5D%0A%20%20Q%5B%22%E7%9B%AE%E6%A0%87%E9%87%8F%20Q%22%5D%20--%3E%20PQ%5B%22%E6%B2%BF%E7%B0%BF%E6%B6%88%E8%80%97%20P(Q)%22%5D%0A%20%20LK%20--%3E%20PQ%0A%20%20MP%20--%3E%20Tiny%5B%22%E4%B8%8B%E4%B8%80%E5%B0%8F%E8%B7%B3%22%5D%0A%20%20MK%20--%3E%20MidS%5B%22%E5%A4%9A%E6%A1%A3%E5%85%AC%E5%85%81%E8%AF%BB%E6%95%B0%22%5D%0A%20%20PQ%20--%3E%20Cost%5B%22%E5%8F%AF%E8%A7%81%E5%86%B2%E5%87%BB%E6%88%90%E6%9C%AC%22%5D%0A%20%20Hid%5B%22%E5%86%B0%E5%B1%B1%20%2F%20%E6%9A%97%E6%B1%A0%22%5D%20-.-%3E%7C%22%E5%8F%AF%E8%A7%81%E8%B7%AF%E5%BE%84%20%E2%89%A0%20%E5%AE%9E%E7%8E%B0%E5%9D%87%E4%BB%B7%22%7C%20PQ%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>深度加权中间价把多档可见量收成读数，或按目标量 \\(Q\\) 沿簿给出 \\(P(Q)\\)；最优档微价格是 \\(K=1\\) 的极限。</li><li>小单看微价格，大单看 \\(P(Q)\\)；线性 Kyle \\(\\lambda\\) 是把阶梯拟合成斜率。</li><li>与 OFI 分工：一个是深度状态，一个是事件流量。</li><li>隐藏流动性使可见 \\(P(Q)\\) 有偏，事后均价对照是质量研究。</li><li>档位、衰减、目标量与可成交性截断必须预先锁定。</li><li>出处：Harris, <em>Trading and Exchanges</em>；大冲击与簿事件见 Cont, Kukanov and Stoikov, 2014；线性冲击基准见 Kyle, 1985。</li></ul>',2))])}const b=l(E,[["render",h]]);export{P as __pageData,b as default};
